"id": "queue-dequeue",
"week": 3,
"group": "Lab 03 · Queue",
"title": "Queue::dequeue()",
"desc": "Remove the element at the head and return it. Throw std::out_of_range when the queue is empty.",
"kind": "lab",
"lib": [
"head",
"tracker",
"node",
"queue_h",
"queue_rest:queue-dequeue",
"use_std"
],
"show": "template <typename Data>\nclass Queue {\nprivate:\n    Node<Data>* head{};\n    Node<Data>* tail{};\n    int length{0};\npublic:\n    // constructors\n    Queue() = default;\n    Queue(std::initializer_list<Data> queue);\n    // copy semantics\n    Queue(const Queue& src);\n    Queue& operator=(const Queue& src);\n    // move semantics\n    Queue(Queue&& src) noexcept;\n    Queue& operator=(Queue&& src) noexcept;\n    // destructor\n    ~Queue();\n\n    void enqueue(const Data& data);\n    Data dequeue();\n    bool is_empty() const;\n    int size() const;\n    const Data& peek() const;\n    void reverse();\n};\n",
"solution": "template<typename Data>\nData Queue<Data>::dequeue() {\n    if (is_empty()) {\n        throw std::out_of_range(\"Queue is empty\");\n    }\n\n    Node<Data> *temp = head;\n    Data data = temp->data;\n    head = head->next;\n\n    if (head == nullptr) {\n        tail = nullptr;\n    }\n\n    --length;\n    delete temp;\n    return data;\n}\n",
